import React, { useState } from 'react';
import './CSS/LoginSignup.css';

const LoginSignup = () => {
  const [state, setState] = useState("Login");
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    email: ""
  });

  const changeHandler = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const login = async () => {
    console.log("Login Function Executed", formData);
    try {
      const response = await fetch('http://localhost:4000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      const responseData = await response.json();

      if (responseData.success) {
        localStorage.setItem('auth-token', responseData.token);
        window.location.replace("/");
      } else {
        alert(responseData.errors || "Login failed");
      }
    } catch (err) {
      alert("Error: Backend server is not running on port 4000.");
    }
  };

  const signup = async () => {
    console.log("Signup Function Executed", formData);
    try {
      const response = await fetch('http://localhost:4000/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      const responseData = await response.json();

      if (responseData.success) {
        localStorage.setItem('auth-token', responseData.token);
        window.location.replace("/");
      } else {
        alert(responseData.errors);
      }
    } catch (err) {
      alert("Error: Backend server is not running on port 4000.");
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault(); // Prevents page reload on submit
    state === "Login" ? login() : signup();
  };

  return (
    <div className='loginsignup'>
      <div className="loginsignup-container">
        <h1>{state}</h1>
        {/* Wrapping in a form tag is essential for browser password managers */}
        <form onSubmit={handleSubmit}>
          <div className="loginsignup-fields">
            {state === "Signup" ? (
              <input 
                name='username' 
                value={formData.username} 
                onChange={changeHandler} 
                type="text" 
                placeholder='Your Name' 
                autoComplete="username" 
                required 
              />
            ) : null}
            <input 
              name='email' 
              value={formData.email} 
              onChange={changeHandler} 
              type="email" 
              placeholder='Email Address' 
              autoComplete="email" 
              required 
            />
            <input 
              name='password' 
              value={formData.password} 
              onChange={changeHandler} 
              type="password" 
              placeholder='Password' 
              autoComplete={state === "Signup" ? "new-password" : "current-password"} 
              required 
            />
          </div>
          <button type="submit">Continue</button>
        </form>

        {state === "Signup" ? (
          <p className="loginsignup-login">Already have an account? <span onClick={() => setState("Login")}>Login Here</span></p>
        ) : (
          <p className="loginsignup-login">Create an account? <span onClick={() => setState("Signup")}>Click Here</span></p>
        )}
        
        <div className="loginsignup-agree">
          <input type="checkbox" name='agree' id='agree' required />
          <p>By continuing, I agree to the terms of use & privacy policy.</p>
        </div>
      </div>
    </div>
  );
};

export default LoginSignup;
